const TYPICAL = { sedan: [4750, 1820, 1455, 2750], coupe: [4600, 1850, 1380, 2700], hatch: [4250, 1770, 1480, 2600], wagon: [4750, 1820, 1500, 2750], suv: [4650, 1870, 1680, 2750], minivan: [5120, 1980, 1750, 3020], pickup: [5650, 2000, 1900, 3550], van: [5450, 2020, 2100, 3350] };
const PREMIUM = new Set(['Lexus', 'Acura', 'Infiniti', 'BMW', 'Mercedes-Benz', 'Audi', 'Volvo', 'Land Rover', 'Cadillac', 'Lincoln', 'Porsche', 'Genesis', 'Jaguar', 'Maserati', 'Alfa Romeo', 'Tesla', 'Lucid', 'Polestar', 'Rivian']);

const hash = text => { let h = 2166136261; for (const c of text) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return h >>> 0; };

/**
 * A make's face in a period: `face` is the nose, `rear` the tail (vehicle-generator.js).
 * Lamps went from upright blocks to swept wedges to slim strips for nearly every make;
 * the grille is what tells them apart.
 */
function brandLook(make, year, shape) {
  const truck = shape === 'pickup' || shape === 'van', tall = shape === 'suv' || shape === 'minivan' || truck;
  const lamp = truck ? (year >= 2019 ? 'stack' : 'block') : year < 2004 ? 'block' : year < 2015 ? 'wedge' : 'slim';
  const rear = { lamp: truck ? 'block' : shape === 'sedan' || shape === 'coupe' ? 'wrap' : year < 2009 ? 'block' : shape === 'minivan' ? 'tall' : 'wrap' };
  if (rear.lamp === 'wrap' && tall) Object.assign(rear, { lampIn: 22, lampDrop: .1, lampH: .16 });
  if (rear.lamp === 'block' && !truck) Object.assign(rear, { lampH: .3, lampDrop: .02 });
  const face = { lamp, fog: year >= 2003 && year < 2019 && !truck };
  const grille = (g, more = {}) => Object.assign(face, { grille: g }, more);
  if (truck) grille('trap', { grilleLow: .42, grilleHalf: 27, lampIn: 31, grilleWide: [.9, 1], bars: 3, intake: shape === 'van', lampH: .2 });
  switch (make) {
    case 'Honda': case 'Acura':
      if (make === 'Acura') { year < 2009 ? grille('trap', { grilleLow: .66 }) : year < 2017 ? grille('trap', { grilleKind: 'chrome', bars: 0, grilleLow: .66, grilleWide: [.5, 1] }) : grille('hex', { grilleLow: .3, hexWide: [.55, 1, .9], hexMid: .72, bars: 0, chrome: false, intake: false }); break; }
      if (!truck) year < 2006 ? grille('trap', { grilleLow: .7, bars: 1 }) : year < 2016 ? grille('trap', { grilleLow: .64, bars: 2 }) : grille('bar', {});
      break;
    case 'Toyota': if (!truck) year < 2007 ? grille('trap', { grilleLow: .72, bars: 1 }) : year < 2014 ? grille('bar', {}) : tall ? grille('hex', { grilleLow: .22, hexWide: [.8, 1, .7], chrome: false, intake: false, bars: 4 }) : grille('mouth', { chrome: false }); break;
    case 'Lexus': year < 2013 ? grille('trap', { grilleLow: .62, bars: 3 }) : grille('spindle', { grilleLow: .08, grilleHalf: 20, intake: false, lampIn: 26 }); break;
    case 'Nissan': case 'Infiniti': if (!truck) year < 2013 ? grille('trap', { grilleLow: .62, bars: 2 }) : grille('trap', { grilleLow: .34, grilleWide: [.45, 1], bars: 0, frame: .022, intake: year < 2019 }); break;
    case 'Hyundai': year < 2011 ? grille('trap', { grilleLow: .66, bars: 2 }) : grille('hex', { grilleLow: .22, hexWide: [.7, 1, .86], intake: false, chrome: year < 2020 }); break;
    case 'Genesis': grille('hex', { grilleLow: .2, hexWide: [.3, 1, .9], hexMid: .7, intake: false, lamp: 'split', bars: 0 }); break;
    case 'Kia': year < 2011 ? grille('trap', { grilleLow: .66, bars: 2 }) : grille('bar', { chrome: year < 2021, wing: false }); break;
    case 'BMW': grille('kidney', { grilleLow: year >= 2019 ? .5 : .6, grilleTop: .98, grilleHalf: year >= 2019 ? 15 : 12, fog: false }); break;
    case 'MINI': grille('hex', { grilleLow: .25, grilleHalf: 17, lamp: 'round', intake: false }); break;
    case 'Mercedes-Benz': if (!truck) grille('trap', { grilleLow: .52, grilleWide: [.8, 1], bars: year >= 2012 ? 1 : 3, emblemR: year >= 2012 ? .075 : .036, grilleHalf: 18 }); else face.emblemR = .07; break;
    case 'Audi': year < 2005 ? grille('trap', { grilleLow: .68 }) : grille('hex', { grilleLow: .12, hexWide: [.8, 1, .92], hexMid: .2, bars: 5, intake: false, grilleHalf: 17, emblemY: .8 }); break;
    case 'Volkswagen': grille('bar', { wing: true, lampH: year >= 2015 ? .09 : undefined }); break;
    case 'Porsche': grille('none', { lamp: 'round', lampR: .1, lampAt: 40, lampY: 1.02, intakeHalf: 42, intakeTop: .42, lampTurn: false, fog: false }); break;
    case 'Subaru': grille('hex', { grilleLow: .55, hexWide: [.8, 1, .9], bars: 1, grilleHalf: 17, fog: true }); break;
    case 'Mazda': year < 2013 ? grille('trap', { grilleLow: .3, grilleWide: [.6, 1], bars: 2, intake: false }) : grille('trap', { grilleLow: .34, grilleWide: [.5, 1], bars: 4, frame: .02, intake: false, grilleHalf: 22, lampIn: 23 }); break;
    case 'Ford': case 'Mercury': if (!truck) year < 2012 ? grille('trap', { grilleLow: .62, bars: 2, grilleWide: [.9, 1] }) : grille('hex', { grilleLow: .34, hexWide: [.7, 1, .8], hexMid: .4, bars: 4 }); break;
    case 'Lincoln': grille('trap', { grilleLow: .42, grilleWide: [.85, 1], bars: 5, grilleHalf: 20 }); break;
    case 'Chevrolet': if (truck) grille('split', { grilleLow: .42, grilleHalf: 28, lampIn: 32, splitAt: .55 }); else grille('split', { grilleLow: year < 2014 ? .5 : .2, intake: year < 2014, splitAt: year < 2014 ? .55 : .72 }); break;
    case 'GMC': grille('trap', { grilleLow: tall ? .4 : .5, grilleWide: [.95, 1], grilleHalf: truck ? 28 : 22, bars: 3, frame: .03, lampIn: truck ? 32 : 26 }); break;
    case 'Cadillac': grille('trap', { grilleLow: .34, grilleWide: [.7, 1], bars: 4, lamp: year >= 2008 ? 'stack' : lamp, grilleHalf: 22, intake: false }); rear.lamp = 'tall'; break;
    case 'Buick': grille('trap', { grilleLow: .5, grilleWide: [.7, 1], bars: 0, grilleKind: 'gloss' }); break;
    case 'Jeep': grille('slots', { grilleLow: .62, grilleHalf: 20, fog: true }); break;
    case 'Dodge': if (!truck) grille('split', { grilleLow: .52, chrome: year < 2011 }); break;
    case 'RAM': grille('trap', { grilleLow: .36, grilleHalf: 26, grilleWide: [.8, 1], bars: 2, frame: .035, lampIn: 31 }); break;
    case 'Chrysler': grille('trap', { grilleLow: .55, grilleWide: [.9, 1], bars: 4 }); break;
    case 'Tesla': case 'Lucid': case 'Rivian': grille('none', { fog: false, intakeTop: .22 }); rear.strip = false; break;
    case 'Volvo': grille('trap', { grilleLow: .5, grilleWide: [.9, 1], bars: 0, grilleHalf: 17, frame: .02 }); rear.lamp = tall || shape === 'wagon' ? 'tall' : 'wrap'; break;
    case 'Land Rover': grille('bar', { chrome: false, wing: false, lamp: year < 2010 ? 'block' : 'slim' }); break;
    case 'Mitsubishi': year < 2016 ? grille('trap', { grilleLow: .3, intake: false, chrome: false }) : grille('hex', { grilleLow: .2, hexWide: [1, .6, .9], intake: false }); break;
    case 'Alfa Romeo': grille('trap', { grilleLow: .45, grilleWide: [.15, 1], grilleHalf: 10, bars: 0, frame: .018 }); break;
    case 'Jaguar': case 'Maserati': grille('trap', { grilleLow: .45, grilleWide: [.85, 1], bars: 0, grilleHalf: 18, frame: .02 }); break;
    default: if (!face.grille) grille('trap', { grilleLow: .6 });
  }
  if (!face.grille) grille('trap', { grilleLow: .62, bars: 2 });
  return { face, rear };
}

/** How the body of its period sits, before the row or the make say otherwise. */
function period(year, shape, make) {
  const look = {};
  if (year < 2004) Object.assign(look, { tumble: shape === 'suv' ? .82 : .76, crown: .03 });
  if (year < 2000 && (shape === 'sedan' || shape === 'coupe')) Object.assign(look, { hoodK: .5, cowlK: .665, deckK: .7, screen: .7 });
  if (year >= 2012 && (shape === 'sedan' || shape === 'hatch' || shape === 'coupe')) Object.assign(look, { screen: .86, noseR: .38, noseW: .8 });
  if (year >= 2012 && shape === 'suv') Object.assign(look, { noseR: .36, noseW: .82, hoodK: .61 });
  if (year >= 2016 && PREMIUM.has(make) && shape !== 'pickup') look.sunroof = .75;
  if (shape === 'suv' && year >= 2008 && !PREMIUM.has(make)) look.archTrim = true;
  if (PREMIUM.has(make)) Object.assign(look, { cladding: false, railKind: 'silver', handles: 'chrome' });
  return look;
}

// The register spells a model as its maker's paperwork did: "COROLLA CROSS", "Fortwo", "Golf GTI".
const plain = text => text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const ALIAS = { 'dodge/ram': 'ram/1500', 'subaru/xv crosstrek': 'subaru/crosstrek', 'volkswagen/golf gti': 'volkswagen/gti', 'mini/cooper': 'mini/hardtop', 'mini/cooper convertible': 'mini/hardtop', 'dodge/caravan grand caravan': 'dodge/grand caravan',
  'toyota/corolla matrix': 'toyota/matrix', 'ram/promaster 2500': 'ram/promaster', 'ram/promaster 1500': 'ram/promaster', 'ram/promaster 3500': 'ram/promaster', 'mercury/mountaineer': 'ford/explorer', 'toyota/prius': 'toyota/prius',
  'chevrolet/silverado 1500': 'chevrolet/silverado', 'gmc/sierra 1500': 'gmc/sierra', 'mercury/mariner': 'ford/escape', 'mercury/milan': 'ford/fusion', 'mercury/sable': 'ford/taurus', 'saturn/outlook': 'gmc/acadia', 'pontiac/g6': 'chevrolet/malibu' };
const models = new Map();
for (const [make, model, shape, generations, shared = {}] of ROWS) models.set(plain(make) + '/' + plain(model), { shape, shared, generations });
function rowsFor(make, model) {
  const m = plain(make), name = plain(model), key = m + '/' + name;
  const exact = models.get(ALIAS[key] || key);
  if (exact) return exact;
  // A BMW is registered by its engine badge: a 328i and a 330i are both a 3 Series, and an M3 is one too.
  if (m === 'bmw') { const n = /^m?([2-8])(\d\d|$)/.exec(name); if (n) return models.get('bmw/' + n[1] + ' series'); }
  if (m === 'mercedes benz') { const n = /^(?:amg )?([a-z]{1,3})(?: class| ?\d)/.exec(name); if (n && models.has(m + '/' + n[1] + ' class')) return models.get(m + '/' + n[1] + ' class'); }
  if (m === 'audi') { const n = /^r?s ?([q]?\d)/.exec(name); if (n) return models.get('audi/' + (n[1].length === 1 ? 'a' + n[1] : n[1])); }
  // A trim or a body spelled into the name: a "Golf Alltrack" is a Golf, a "Wrangler JK" a Wrangler.
  const words = name.split(' ');
  for (let k = words.length - 1; k > 0; k--) { const base = models.get(m + '/' + words.slice(0, k).join(' ')); if (base) return base; }
  return null;
}

const cache = new Map();
/**
 * The design for a registered car, in the form of an exterior: `{ id, make, model, shape, years, design, wheels }`.
 * The same generation of a model in the same body is one design, whoever asks.
 */
export function designFor(make, model, year, shape) {
  const entry = rowsFor(make, model);
  let span, size, own = {}, known = false;
  if (entry) {
    // The generation sold that year, or the nearest: a late registration of an old shape is still that shape.
    const g = entry.generations.reduce((best, row) => { const miss = r => Math.max(0, r[0] - year, year - r[1]); return miss(row) < miss(best) ? row : best; });
    span = [g[0], g[1]]; size = g.slice(2, 6); own = { ...entry.shared, ...g[6] }; known = true;
    // A row drawn for the saloon still serves the hatchback or coupe of that generation.
    if (entry.shape !== shape && !own.shape) own = Object.fromEntries(Object.entries(own).filter(([k]) => !['rearHeader', 'glassRun', 'rearDrop', 'deck', 'deckK', 'rear', 'tailY'].includes(k)));
  } else {
    // An unlisted model: typical for its style, nudged so that two of them are not twins.
    const h = hash(make + '/' + model), start = 1990 + (h % 6) + Math.floor((year - 1990 - (h % 6)) / 7) * 7, big = ((h >>> 3) % 100) / 100 - .5;
    span = [start, start + 6];
    const t = TYPICAL[shape] || TYPICAL.sedan;
    size = [t[0] * (1 + big * .08), t[1] * (1 + big * .04), t[2] * (1 + (((h >>> 11) % 100) / 100 - .5) * .05), t[3] * (1 + big * .07)].map(Math.round);
    own = { screen: undefined };
  }
  const drawn = own.shape || shape, id = `${make}-${model}-${span[0]}-${drawn}`.toLowerCase().replace(/[^a-z0-9]+/g, '-');
  if (cache.has(id)) return cache.get(id);
  const mid = Math.min(Math.max(year, span[0]), span[1]), look = brandLook(make, known ? Math.min(span[0] + 1, span[1]) : mid, drawn), { face: ownFace, rear: ownRear, shape: _, ...body } = own;
  for (const key of Object.keys(body)) if (body[key] === undefined || body[key] === null) delete body[key];
  const design = { ...period(known ? span[0] + 1 : mid, drawn, make), ...body, shape: drawn, L: size[0] / 1000, W: size[1] / 1000, H: size[2] / 1000, WB: size[3] / 1000,
    face: { ...look.face, ...ownFace }, rear: { ...look.rear, ...ownRear } };
  const spec = { id, make, model, shape, years: span, generated: true, known, design, wheels: designWheels(design) };
  cache.set(id, spec);
  return spec;
}

/** Every model with rows of its own, for the catalog page and the tests. */
export const DESIGNED = ROWS.map(([make, model, shape, generations]) => ({ make, model, shape, generations: generations.map(g => g.slice(0, 2)) }));
